          "easyMarkdown": "**問題：** 通常の建物賃貸借（定期借家を除く）について、正しいものはどれか。\n\n1. 期間を定めていない建物賃貸借は、大家・借主のどちらが解約を申し入れても、一律6か月後に終了する。\n2. 2年間の契約で双方が満了の1年前から6か月前までに更新拒絶等の通知をしなかった場合、再び2年間の契約として自動更新される。\n3. 造作買取請求権（借主が設置した一定の設備等を大家に買い取ってもらう権利）を行使しないという特約は有効。\n4. 取り壊す予定の建物を、その取り壊しまで貸す契約は、必ず公正証書で契約しなければならない。\n\n(正解 3)\n\n| 肢 | 判定・理由 |\n|--------|--------|\n| 1 | 原則として大家の解約申入れは6か月、借主からは3か月。大家には正当事由も必要。 |\n| 2 | 法定更新後は**期間の定めのない契約**となる。 |\n| **3** | 造作買取請求権を排除する特約は有効。 |\n| 4 | 取り壊し予定の建物賃貸借では所定の書面による契約が必要だが、公正証書限定ではない。 |\n\n**暗記：普通借家の法定更新は「期間なし」。造作買取請求は特約で排除可能。**",
