          "easyMarkdown": "**問題：** 固定資産税について、正しいものはどれか。\n\n1. 小規模住宅用地（住宅1戸当たり200㎡まで）の固定資産税の課税標準は、原則価格の3分の1となる。\n2. 固定資産課税台帳（固定資産の評価や課税情報を記載する帳簿）の閲覧で、住所を明らかにすると生命・身体に危険が及ぶおそれがある場合、市町村長は住所を伏せて閲覧させることができる。\n3. 固定資産税の税額が土地30万円、家屋20万円、償却資産150万円未満なら、原則課税されない。\n4. 登記名義人が1月1日より前に亡くなった場合、新しい名義人が登録されていないと誰にも固定資産税を課税できない。\n\n(正解 2)\n\n| 肢 | 判定・理由 |\n|--------|--------|\n| 1 | 小規模住宅用地の固定資産税は原則**6分の1**。3分の1は都市計画税の特例と混同しやすい。 |\n| **2** | 安全上の理由で住所の非表示などができる。 |\n| 3 | 免税点は**税額ではなく課税標準額**で判断。土地30万円、家屋20万円、償却資産150万円。 |\n| 4 | 名義人が死亡していても、現所有者などに課税される場合がある。 |\n\n**暗記：固定資産税は小規模住宅用地6分の1！**",
