          "easyMarkdown": "**問題：** 課税事業者である宅建業者A・Bの報酬について、誤っている記述の組合せはどれか。 ア・イの賃料等は消費税相当額を含まない。ウは建物の消費税相当額を含む。広告料金は含めないものとする。\n\n**ア**　Aが店舗の賃貸借を媒介。月額賃料24万円、返還されない権利金（賃借権設定の対価）1,400万円。貸主・借主からそれぞれ52万8,000円の報酬を受け取った行為は違法である。 ア・イの賃料等は消費税相当額を含まない。ウは建物の消費税相当額を含む。広告料金は含めないものとする。\n\n**イ**　長期未利用の土地で賃料月5万円。貸主側代理業者Aが4万円、借主側代理業者Bが事前承諾を得て7万円受領した行為は適法である。 ア・イの賃料等は消費税相当額を含まない。ウは建物の消費税相当額を含む。広告料金は含めないものとする。\n\n**ウ**　税込200万円（土地90万円）の土地付建物を売買媒介したとき、報酬額の事前取決めがなくても、売主と買主はそれぞれ仲介業者へ最低10万4,500円を払わなければならない。 ア・イの賃料等は消費税相当額を含まない。ウは建物の消費税相当額を含む。広告料金は含めないものとする。\n\n--- ア・イの賃料等は消費税相当額を含まない。ウは建物の消費税相当額を含む。広告料金は含めないものとする。\n\n1＝ア・イ　2＝イ・ウ　3＝ア・ウ　4＝ア・イ・ウ ア・イの賃料等は消費税相当額を含まない。ウは建物の消費税相当額を含む。広告料金は含めないものとする。\n\n(正解 4（すべて誤り）) ア・イの賃料等は消費税相当額を含まない。ウは建物の消費税相当額を含む。広告料金は含めないものとする。\n\n| 記号 | 判定・理由 |\n|--------|--------|\n| ア | 店舗等の権利金は売買代金とみなして報酬計算できる。1,400万円なら片側税込52万8,000円で**適法**。 |\n| イ | 長期空家等の特例があっても、借主側から受領できる上限は月額賃料の1.1倍。5万5,000円なので7万円は超過。 |\n| ウ | 報酬告示は受領できる**上限**を定める制度。最低支払額を決めているわけではない。 | ア・イの賃料等は消費税相当額を含まない。ウは建物の消費税相当額を含む。広告料金は含めないものとする。\n\n**暗記：上限と最低報酬は違う！ 空家特例があっても借主側の上限に注意。** ",
