          "easyMarkdown": "**問題：** 宅建業法37条の書面について、正しいものはどれか。\n\n1. 事業用土地の賃貸借を媒介した場合、当事者が宅建業者なら37条書面は不要。\n2. 自ら売主として中古建物を売却する場合、建物の構造耐力上主要な部分（柱・梁など）等について当事者双方が確認した事項を37条書面に記載する。\n3. 土地の売買媒介で天災等の損害負担の取決めがない場合は、「定めなし」と37条書面に必ず書く。\n4. 建物売買で住宅ローン等のあっせん（融資先の紹介）を取り決めた場合でも、融資が成立しないときの措置は37条書面に不要。\n\n(正解 2)\n\n| 肢 | 判定・理由 |\n|--------|--------|\n| 1 | 業者間でも37条書面の交付義務はある。 |\n| **2** | 中古建物の売買で当事者が確認した構造・雨水侵入防止部分の事項は37条の記載対象。 |\n| 3 | 不可抗力の取決めが**ある場合に**記載する。定めがなければ「定めなし」の記載義務はない。 |\n| 4 | 融資が成立しない場合の措置は、あっせんの定めがあれば必要事項。 |\n\n**暗記：37条書面は「契約で定めた場合だけ書く事項」がある！**",
