          "sourcePage": 3,
          "lawNote": "問題文の出題年・日付などの条件は、その年度の設定を保っています。正解は出題当時の公式正解番号です。年度一覧の「2026年4月1日基準の主な改正注意」も合わせて確認してください。",
          "contentStatus": "official-compared",
          "lawReviewStatus": "major-amendments-noted",
          "corrections": [],
          "title": "委任契約と請負契約",
          "easyMarkdown": "**問題：委任契約（人に事務処理を任せる契約）と準委任契約（法律行為以外の事務を任せる契約）について、誤っている説明はどれか。**\n\n**選択肢1**\n\nマンションの売主が、買主に対して専有部分（区分所有者が自分で所有する部屋など）の防火戸の操作方法を説明する義務を負っている。\n\nこの場合、売主から販売業務を委託（業務を任せること）され、売主と一体となってマンションの販売事務全般を担当した宅建業者も、買主に対し信義則上（信頼関係を裏切らず、誠実に行動すべきという原則に基づき）、防火戸の操作方法を説明する義務を負うことがある。\n\n---\n\n**選択肢2**\n\n受任者（仕事を頼まれた人）は、原則として、委任者（仕事を頼んだ人）から許諾（許可）を得た場合、またはやむを得ない事由（避けられない事情）がある場合でなければ、復受任者（さらに仕事を任せる別の人）を選ぶことができない。\n\n---\n\n**選択肢3**\n\n委任契約で、本人が死亡しても代理権（本人に代わって法律行為をする権限）が消滅しないという合意をしたうえで、代理人に権限を与えていた。\n\nこの場合、本人が死亡しても代理権は消滅しない。\n\n---\n\n**選択肢4**\n\n委任契約は、一方が仕事を完成させることを約束し、もう一方が完成した仕事の結果に対して報酬（仕事の対価）を支払うことを約束しなければ成立しない。\n\n(正解 4) **民法632条・643条など**\n\n| 肢 | 判定 | なぜ？ |\n|--------|--------|--------|\n| 1 | ○ | 販売業者にも説明義務が生じる場合があるという判例。 |\n| 2 | ○ | 民法644条の2。原則、無断で復受任者は選べない。 |\n| 3 | ○ | 本人死亡後も代理権を存続させる合意は、判例上有効になり得る。 |\n| 4 | × | これは委任ではなく、**請負契約**の説明。 |\n\n**不動産実務で考えると**\n\n- **委任：** 不動産の売却に関する事務を任せる。\n- **請負：** 大工に建物を完成させてもらう。\n\n※実際の媒介契約は媒介特有の法的性質もあり、単純に委任そのものとは限らない。\n\n**暗記：「委任は事務処理、請負は仕事の完成」**\n\n出典：令和6年度公式試験・問2。\n\n---",
          "lawSources": []
