          "easyMarkdown": "**問題：正しい記述は何個あるか。**\n\n地主Aの土地に、Bの地上権（他人の土地に建物などを所有するために利用できる権利）が先に設定・登記された。その後、銀行Cの抵当権（返済されないとき土地などから優先的に回収できる権利）が設定・登記された。\n\nBが土地の所有権も取得した場合に、地上権が消滅するかを考える。\n\n| 記号 | 選択肢の内容 |\n|--------|--------|\n| ア | BがAから土地を**買った**なら、Bの地上権は消滅する。 |\n| イ | Aが死亡しBが**単独相続**したなら、地上権は消滅する。 |\n| ウ | Aから**代物弁済**（お金の返済の代わりに土地などを渡すこと）で取得したなら、地上権は消滅する。 |\n| エ | Aから土地を**贈与**されたなら、地上権は消滅する。 |\n\n選択肢は、**1＝1個、2＝2個、3＝3個、4＝0個**。\n\n(正解 4) **正しい記述は0個。**\n\nア〜エはすべて誤り。理由は**混同（こんどう＝所有権と地上権などが同じ人に集まること）**の例外。\n\n普通ならBが土地の所有権を取得すると、Bの地上権は混同で消滅する。しかし今回は、土地に後から設定された**銀行Cの抵当権**がある。\n\n地上権が消えるとCとの優先関係に影響するため、民法179条の例外によってBの地上権は残る。\n\n**覚え方：混同で原則消滅。ただし第三者の権利を害するなら残る！** \n\n---",
