          "easyMarkdown": "**問題：民法と判例によれば、正しいものはどれか。**\n\nAが所有する建物をBに賃貸（貸すこと）し、Bは引渡しを受けて居住している。\n\n**選択肢1**\n\nCが「大家Aからこの建物を買った」と嘘をつき、Bはそれを信じて自分の意思で建物の占有（事実上の支配）をCに渡した。この場合、AはCに対して占有回収の訴え（奪われた占有を取り戻す裁判）で返還を請求できない。\n\n---\n\n**選択肢2**\n\nBが建物入口を閉め、大家Aを中に入れなかった。これによりAの間接占有（借主などを通じて物を支配している状態）が侵奪（占有を奪われること）されたため、AはBに占有回収の訴えを起こせる。\n\n---\n\n**選択肢3**\n\n借主Bが死亡してDが単独相続しても、DはBの死亡を知るまで占有を引き継がない。\n\n---\n\n**選択肢4**\n\n大家Aと借主Bがともに死亡すれば、建物賃貸借契約は当然に終了する。\n\n(正解 1)\n\n| 肢 | 判定・理由 |\n|--------|--------|\n| **1** | Bはだまされて任意に占有を渡した。占有回収の訴えが前提とする侵奪には当たらない。 |\n| 2 | 賃借人Bが大家の立入りを拒んだだけでは、Aの間接占有が侵奪されたとはいえない。 |\n| 3 | 占有は相続で承継される。相続人が死亡を知った時からではない。 |\n| 4 | 原則として賃貸借上の地位も相続される。双方の死亡で当然には終了しない。 |\n\n**覚え方：占有回収は「奪われた」が基本。だまされて渡した場合とは区別！** \n\n---",
