          "easyMarkdown": "**問題：債務引受（他人の借金を引き受けること）について、正しいものはどれか。**\n\nまず2種類を区別しよう。\n\n- **免責的債務引受：** 元の借主が原則として借金から抜け、新しい人が返済義務を負う。\n- **併存的債務引受：** 元の借主の義務は残り、新しい人も返済義務を負う。\n\n**選択肢1**\n\n免責的債務引受を、元の借主と新しい引受人だけで契約する場合、貸主の承諾（同意）は不要である。\n\n---\n\n**選択肢2**\n\n併存的債務引受を、元の借主と引受人との間で契約した場合は、貸主が引受人に承諾した時に効力が生じる。\n\n---\n\n**選択肢3**\n\n併存的債務引受を、貸主と引受人との間で契約した場合は、元の借主が引受人に承諾した時に効力が生じる。\n\n---\n\n**選択肢4**\n\n借主が借りている物件を別の人に転貸（又貸し）する場合、大家の承諾は不要である。\n\n(正解 2)\n\n| 肢 | 判定・理由 |\n|--------|--------|\n| 1 | 免責的債務引受を借主と引受人で行うには、貸主の承諾が必要。 |\n| **2** | 民法470条3項のとおり。 |\n| 3 | 貸主と引受人が直接契約する併存的債務引受なら、元の借主の承諾は不要。 |\n| 4 | 転貸には原則として賃貸人の承諾が必要（民法612条）。 |\n\n**覚え方：貸主は誰に返してもらうかが重要。免責的は特に貸主を守る！** \n\n---",
