          "easyMarkdown": "**問題：建物状況調査（中古住宅の構造や雨漏りなどを専門家が調べる検査）について、誤っているものはどれか。**\n\n1. 建物状況調査は、構造耐力上主要な部分（柱・梁など主要な構造部分）や雨水の浸入を防ぐ部分を、国の定める専門家が調べるものである。\n2. 調査を実施する者は、原則として所定の講習を修了した建築士である。\n3. 中古住宅の売買を仲介する業者が建物状況調査の実施者を紹介しても、その紹介のための料金を通常の媒介報酬とは別に受け取れない。\n4. 中古建物の**賃貸借**を仲介した業者は、構造耐力上主要な部分等について当事者が確認した事項を、37条書面に必ず記載しなければならない。\n\n(正解 4（誤り）)\n\n| 肢 | 判定・理由 |\n|--------|--------|\n| 1 | 構造・雨水侵入防止部分の調査。 |\n| 2 | 所定の講習を修了した建築士が行う。 |\n| 3 | あっせんは媒介業務の一環で、別料金不可。 |\n| **4** | その37条書面の記載は**既存建物の売買・交換**が対象で、賃貸借では不要。 |\n\n**覚え方：「建物状況調査の結果確認事項は、売買の37条。貸借は違う！」**",
