          "easyMarkdown": "**問題：B所有の100㎡の住宅をAが2年間借りる。定期建物賃貸借（期間満了時に更新しない契約）について、誤っているものはどれか。**\n\n1. 大家Bが定期借家の契約書を契約前に渡し、更新されないことを説明すれば、別の事前説明書面がなくても定期借家として有効になる。\n2. 借主Aが引渡しを受けていれば、1年後に建物を購入したCに対しても賃借権を主張できる。\n3. Aが転勤や介護などのやむを得ない事情で生活の本拠として使えなくなった場合、中途解約禁止特約があっても解約を申し入れられる。\n4. 敷金（家賃未払いなどの担保として預ける金銭）の返還は、賃貸借が終了しただけではなく、原則として建物を明け渡した後になる。\n\n(正解 1（誤り）)\n\n| 肢 | 判定・理由 |\n|--------|--------|\n| **1** | 定期借家の更新がないことは、契約書とは別に事前説明する必要がある。 |\n| 2 | 建物の引渡しが対抗要件となる。 |\n| 3 | 200㎡未満の居住用定期借家には、一定の場合に借主からの中途解約が認められる。 |\n| 4 | 原則として賃貸借終了と建物返還の両方が必要。 |\n\n**2026年の法改正注意**\n\n2022年5月から、定期借家の契約や事前説明に所定の電磁的方法（電子データ）も利用できるようになった。\n\nただし、**契約と別の事前説明が必要**という結論は変わらない。",
