          "easyMarkdown": "**問題：建築基準法について、正しいものはどれか。**\n\n1. 第一種低層住居専用地域には、原則として神社や寺院を建築できない。\n2. 総合設計制度（一定の公開空地などを設けることで容積率等を緩和する制度）では、容積率・高さに加え建蔽率も緩和できる。\n3. 現況幅員1.8m未満の道を建築基準法42条2項の道路として指定するには、あらかじめ建築審査会の同意が必要。\n4. 第一種住居地域にも、原則10mまたは12mという絶対高さ制限がある。\n\n(正解 3)\n\n| 肢 | 判定・理由 |\n|--------|--------|\n| 1 | 神社・寺院などは第一種低層住居専用地域でも建築できる。 |\n| 2 | 総合設計制度の緩和対象に建蔽率は含まれない。 |\n| **3** | 幅員1.8m未満の場合には建築審査会の同意が必要。 |\n| 4 | 絶対高さ制限は第一種・第二種低層住居専用地域、田園住居地域などが対象。 |\n\n**暗記：2項道路の1.8m未満は審査会同意。総合設計でも建蔽率は緩和されない！**",
