          "easyMarkdown": "**問題：35条の重要事項説明について、正しいものはどれか。**\n\n1. 既存住宅の売買では、検査済証（建物が検査に合格したことを示す書類）など、建築・維持保全に関する所定の書類の保存状況を説明する。\n2. 売買代金の金額と支払時期・支払方法を、35条で必ず説明する。\n3. 水害ハザードマップ（浸水などの危険を示す地図）があれば、その存在だけ伝えればよく、物件の所在地を示す必要はない。\n4. 物件の引渡し時期は35条の重要事項説明で必ず説明する。\n\n(正解 1)\n\n| 肢 | 判定・理由 |\n|--------|--------|\n| **1** | 既存住宅の建築・維持保全書類の保存状況は説明対象。 |\n| 2 | 代金と支払時期・方法は37条書面の事項。 |\n| 3 | ハザードマップ上の**物件の位置**を示して説明する。 |\n| 4 | 引渡し時期は37条書面の事項。 |\n\n**暗記：「35条は物件の重要事項、37条は契約内容。ハザードマップでは所在地を示す！」**",
